import{_ as r,o as e,c as a,a5 as o}from"./chunks/framework.CXroN2RO.js";const n="/study/images/network/network-basics.svg",P=JSON.parse('{"title":"ネットワークの基本 — アプリのデータが相手へ届くまで","description":"","frontmatter":{"title":"ネットワークの基本 — アプリのデータが相手へ届くまで","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"network","summary":"ネットワーク、クライアントとサーバー、パケット、プロトコルを定義し、Webページを開く操作から通信の層と往復をたどる。","aliases":["ネットワーク","インターネット","クライアント","サーバー","プロトコル","パケット","通信の層","Ethernet","Wi-Fi"],"verification":"MDNのWeb基礎とIETFのIP・TCP・UDP・HTTP仕様に照合（2026-11-07）"}},"headers":[],"relativePath":"network/network-basics.md","filePath":"network/network-basics.md"}'),s={name:"network/network-basics.md"};function l(i,t,h,d,c,f){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="ネットワークの基本-—-アプリのデータが相手へ届くまで" tabindex="-1">ネットワークの基本 — アプリのデータが相手へ届くまで <a class="header-anchor" href="#ネットワークの基本-—-アプリのデータが相手へ届くまで" aria-label="Permalink to &quot;ネットワークの基本 — アプリのデータが相手へ届くまで&quot;">​</a></h1><p><strong>ネットワーク</strong>は、機器をつないでデータをやり取りできるようにした仕組みです。家庭のPCとスマートフォンがつながる範囲もネットワークで、そのようなネットワーク同士を世界規模でつないだものが<strong>インターネット</strong>です。通信するときは、端末に入っているアプリ、OS、通信機器がそれぞれ仕事を受け持ちます。<a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/How_does_the_Internet_work" target="_blank" rel="noreferrer">MDNのインターネットの仕組み</a></p><h2 id="クライアントとサーバーは会話の役割" tabindex="-1">クライアントとサーバーは会話の役割 <a class="header-anchor" href="#クライアントとサーバーは会話の役割" aria-label="Permalink to &quot;クライアントとサーバーは会話の役割&quot;">​</a></h2><p>Webページを見るとき、ブラウザーは「このページのデータをください」という<strong>要求</strong>を送り、相手は結果を<strong>応答</strong>として返します。要求する側を<strong>クライアント</strong>、要求を受け付ける側を<strong>サーバー</strong>と呼びます。「サーバー」はその役割を果たすプログラムを指すことも、そのプログラムが動く機器を指すこともあります。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-3.3" target="_blank" rel="noreferrer">HTTPのクライアントとサーバー</a></p><p>ゲームでも、クライアントが操作を送り、サーバーが更新した状態を返す構成があります。また、あるPCが外部のサーバーへ要求しながら、別の通信では他のPCからの要求を受けることもできます。役割は、どの通信を見ているかで決まります。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-3.3" target="_blank" rel="noreferrer">HTTPの接続と要求の流れ</a></p><h2 id="プロトコルはデータの形式と手順" tabindex="-1">プロトコルはデータの形式と手順 <a class="header-anchor" href="#プロトコルはデータの形式と手順" aria-label="Permalink to &quot;プロトコルはデータの形式と手順&quot;">​</a></h2><p>相手と通信するには、どの欄に宛先を書くか、どんな順で要求するか、応答をどう読むかを合わせます。このような約束を<strong>プロトコル</strong>と呼びます。Webページの要求にはHTTP、IPアドレスを使った転送にはIPというように、担当する仕事ごとに約束があります。<a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Web_standards/How_the_web_works" target="_blank" rel="noreferrer">MDNのWebが動く仕組み</a></p><table tabindex="0"><thead><tr><th>名前</th><th>担当する仕事</th></tr></thead><tbody><tr><td><strong>HTTP</strong></td><td>ページなどへの要求と、応答の意味・形式を定める。</td></tr><tr><td><strong>TCP</strong></td><td>送ったデータを、相手が順序のそろったバイト列として読み取れるようにする。欠けた部分は再送する。バイトはデータの量を数える単位。</td></tr><tr><td><strong>UDP</strong></td><td>一件ずつのメッセージを送る。届く順番、再送、重複への対応は用途に合わせて上の層で扱う。</td></tr><tr><td><strong>IP</strong></td><td>宛先IPアドレスを使い、複数のネットワークをまたいでデータを転送する。</td></tr><tr><td><strong>Ethernet・Wi-Fi</strong></td><td>有線や無線のリンク上で、隣接する機器とのデータの受け渡しを担当する。</td></tr></tbody></table><p>例えばTCPを選ぶかUDPを選ぶかで、アプリがデータの区切りや欠落を扱う方法が変わります。HTTP/3ではUDPの上にQUICを使い、QUICが信頼性のあるストリームなどを提供します。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-2.2" target="_blank" rel="noreferrer">TCPの基本</a> · <a href="https://www.rfc-editor.org/rfc/rfc768.html" target="_blank" rel="noreferrer">UDPの仕様</a> · <a href="/study/network/quic-and-http3.html">QUICとHTTP/3</a></p><h2 id="データを小さな単位にして運ぶ" tabindex="-1">データを小さな単位にして運ぶ <a class="header-anchor" href="#データを小さな単位にして運ぶ" aria-label="Permalink to &quot;データを小さな単位にして運ぶ&quot;">​</a></h2><p>大きなページや画像を運ぶとき、通信に使うデータは複数の単位に分かれます。ネットワーク上で運ぶ単位を広く<strong>パケット</strong>と呼びます。各パケットには、運びたい中身に加えて、宛先などを示す<strong>ヘッダー</strong>が付きます。段階ごとの名前では、TCPの単位を<strong>セグメント</strong>、Ethernet上の単位を<strong>フレーム</strong>と呼びます。<a href="https://www.rfc-editor.org/rfc/rfc9293.html#section-2.2" target="_blank" rel="noreferrer">TCPセグメントとIPデータグラム</a> · <a href="https://www.rfc-editor.org/rfc/rfc791.html#section-3.1" target="_blank" rel="noreferrer">IPヘッダー</a></p><figure class="study-figure"><img src="'+n+'" alt="送信側のHTTPデータにTCP、IP、リンクの情報が順に付き、ネットワークを通る。受信側はリンク、IP、TCPの順に処理し、HTTPのデータをアプリへ渡す。" width="760" height="436" loading="lazy"><figcaption>HTTP/1.1をTCPで送る例です。矢印は処理の担当を表し、各段のデータが同じ大きさの一件になることは表しません。<a href="/study/images/network/network-basics.svg" target="_blank" rel="noopener noreferrer">通信の層の図を拡大</a></figcaption></figure><p>上の層は下の層の機能を使います。HTTPは要求と応答を決め、TCPはそのデータを運ぶための順序を扱い、IPは宛先へ向けた転送を扱います。リンク上のフレームは経由する区間ごとに作られ、宛先IPから次の経由先を選ぶ機器を<strong>ルーター</strong>と呼びます。<a href="https://www.rfc-editor.org/rfc/rfc1122.html#section-1.1.3" target="_blank" rel="noreferrer">インターネットの通信の層</a> · <a href="/study/network/ip-routing-and-ethernet.html">IPルーティングとEthernetフレーム</a></p><h2 id="webページを開く操作からたどる" tabindex="-1">Webページを開く操作からたどる <a class="header-anchor" href="#webページを開く操作からたどる" aria-label="Permalink to &quot;Webページを開く操作からたどる&quot;">​</a></h2><p>新しくHTTPSのページを開く場面を、HTTP/1.1またはHTTP/2を使う場合で考えます。キャッシュや既存の接続を使える場合は、一部の処理を再利用できます。<a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-3.3" target="_blank" rel="noreferrer">HTTPの接続とキャッシュ</a> · <a href="/study/network/http-caching.html">HTTPキャッシュ</a></p><ol><li>ブラウザーがURLを読み、接続先のホスト名と、要求するページのパスを取り出します。</li><li><strong>名前解決</strong>で、ホスト名に対応する接続先IPアドレスの候補を調べます。DNSは、そのために使う名前の仕組みです。</li><li>接続先のIPアドレスとポートを決め、TCPで接続します。HTTPSではTLSで通信を保護し、証明書などで相手を確認します。</li><li>HTTPの要求を送り、サーバーの応答を受け取ります。</li><li>ブラウザーが受け取ったHTMLを読み、画像やスタイルシートなどの追加のデータを取得して表示します。</li></ol><p>この流れを読むと、名前が見つかる段階、相手との接続、HTTPの応答、ブラウザーの表示を順に追えます。例えば「名前解決は成功したが接続を確立できない」と「接続後にHTTPのエラー応答が返る」では、調べる場所が変わります。<a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Web_standards/How_the_web_works" target="_blank" rel="noreferrer">MDNのWebが動く仕組み</a> · <a href="/study/network/tls-https.html">TLSとHTTPS</a></p><h2 id="ゲームの通信で同じ用語を読む" tabindex="-1">ゲームの通信で同じ用語を読む <a class="header-anchor" href="#ゲームの通信で同じ用語を読む" aria-label="Permalink to &quot;ゲームの通信で同じ用語を読む&quot;">​</a></h2><p>オンラインゲームで小さな状態更新を送るときも、アプリが作ったデータをOSや通信機器が相手へ運びます。ゲームが何を確定させたいかによって、TCP、UDP、QUICなどから使う方式を選びます。届くまでの時間や、失われた更新の扱いは、ゲームの状態をどう進めるかとつながります。<a href="https://www.rfc-editor.org/rfc/rfc8085.html#section-3" target="_blank" rel="noreferrer">UDPの用途と注意点</a> · <a href="/study/network/latency-throughput-and-queues.html">通信の遅延・帯域・待ち行列</a></p><h2 id="関連記事" tabindex="-1">関連記事 <a class="header-anchor" href="#関連記事" aria-label="Permalink to &quot;関連記事&quot;">​</a></h2><ul><li><a href="/study/network/ip-addresses-and-ports.html">IPアドレス・ポート・ホスト名</a></li><li><a href="/study/network/home-network-devices.html">家庭のネットワーク機器</a></li><li><a href="/study/network/dns-resolution.html">DNSと名前解決</a></li><li><a href="/study/network/tcp-sockets.html">ソケットとTCP通信</a></li><li><a href="/study/network/http-messages.html">HTTP通信</a></li></ul>',21)])])}const T=r(s,[["render",l]]);export{P as __pageData,T as default};
